const createLevelContent = (
  level: number,
  theme: 'light' | 'dark'
): React.ReactNode => {
  if (level >= 6) {
    return (
      <div style={{ padding: '0' }}>
        <Accordion
          type="menu"
          summary="Final Menu Item"
          onClick={() => console.log('Menu clicked')}
          styles={{
            theme,
            level: level + 1,
            levelIndentBase: 16,
            levelIndentIncrement: 12,
            outline: false,
          }}
        />
      </div>
    )
  }

  return (
    <div style={{ padding: '0' }}>
      <Accordion
        type="menu"
        summary={`Overview ${level + 1}`}
        onClick={() => console.log('Overview clicked')}
        styles={{
          theme,
          level: level + 1,
          levelIndentBase: 16,
          levelIndentIncrement: 12,
          outline: false,
        }}
      />
      <Accordion
        summary={`Dashboard ${level + 1}`}
        details={createLevelContent(level + 1, theme)}
        styles={{
          theme,
          level: level + 1,
          levelIndentBase: 16,
          levelIndentIncrement: 12,
          outline: false,
        }}
      />
      <Accordion
        type="menu"
        summary={`Reports ${level + 1}`}
        href="/reports"
        styles={{
          theme,
          level: level + 1,
          levelIndentBase: 16,
          levelIndentIncrement: 12,
          outline: false,
        }}
      />
      <Accordion
        summary={`Settings ${level + 1}`}
        details={createLevelContent(level + 1, theme)}
        styles={{
          theme,
          level: level + 1,
          levelIndentBase: 16,
          levelIndentIncrement: 12,
          outline: false,
        }}
      />
      <Accordion
        type="menu"
        summary={`Profile ${level + 1}`}
        onClick={() => console.log('Profile clicked')}
        isActive={level === 0}
        styles={{
          theme,
          level: level + 1,
          levelIndentBase: 16,
          levelIndentIncrement: 12,
          outline: false,
        }}
      />
    </div>
  )
}

